const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}
const NAME = /^[A-Za-z0-9_./:-]+$/
const UINT = /^(0|[1-9][0-9]*)$/
class Fail extends Error {}
const fail = (m) => { throw new Fail(m) }
const num = (s, field, least) => {
  if (!UINT.test(s) || BigInt(s) < BigInt(least)) fail(`${field} must be an integer of at least ${least}`)
  return BigInt(s)
}

function run(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const states = new Map()
  const out = []
  const stats = new Map()
  let started = false
  let last = null
  let n = 0
  for (const raw of lines) {
    n++
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) continue
    const t = line.split(/\s+/)
    try {
      const d = t[0]
      if (d === 'bucket' || d === 'window' || d === 'route' || d === 'event') {
        if (d !== 'event' && started) fail('declarations must come before the first event')
      } else fail(`unknown directive ${d}`)
      if (d === 'bucket') {
        if (t.length !== 5) fail('expected bucket <name> <capacity> <refill> <per>')
        if (!NAME.test(t[1])) fail(`invalid policy name ${t[1]}`)
        const capacity = num(t[2], 'capacity', 1)
        const refill = num(t[3], 'refill', 0)
        const per = num(t[4], 'per', 1)
        if (policies.has(t[1])) fail(`policy ${t[1]} is declared twice`)
        policies.set(t[1], { name: t[1], kind: 'bucket', capacity, refill, per })
      } else if (d === 'window') {
        if (t.length !== 4) fail('expected window <name> <limit> <span>')
        if (!NAME.test(t[1])) fail(`invalid policy name ${t[1]}`)
        const limit = num(t[2], 'limit', 0)
        const span = num(t[3], 'span', 1)
        if (policies.has(t[1])) fail(`policy ${t[1]} is declared twice`)
        policies.set(t[1], { name: t[1], kind: 'window', limit, span })
      } else if (d === 'route') {
        if (t.length < 3) fail('expected route <prefix> <policy>...')
        if (!NAME.test(t[1])) fail(`invalid route prefix ${t[1]}`)
        if (routes.has(t[1])) fail(`prefix ${t[1]} is routed twice`)
        for (const p of t.slice(2)) if (!policies.has(p)) fail(`unknown policy ${p}`)
        routes.set(t[1], t.slice(2).map((p) => policies.get(p)))
      } else {
        if (t.length !== 3) fail('expected event <tick> <key>')
        const tick = num(t[1], 'tick', 0)
        const key = t[2]
        if (!NAME.test(key)) fail(`invalid key ${key}`)
        if (last !== null && tick < last) fail(`tick ${tick} is before tick ${last}`)
        started = true
        last = tick
        let best = null
        for (const p of routes.keys()) if (key.startsWith(p) && (best === null || p.length > best.length)) best = p
        let denier = null
        if (best !== null) {
          const ps = routes.get(best)
          const sts = ps.map((p) => {
            const id = p.name + '\0' + key
            let s = states.get(id)
            if (!s) {
              s = p.kind === 'bucket' ? { v: p.capacity * p.per, at: tick } : { ticks: [] }
              states.set(id, s)
            }
            if (p.kind === 'bucket') {
              s.v += p.refill * (tick - s.at)
              s.at = tick
              if (s.v > p.capacity * p.per) s.v = p.capacity * p.per
            } else {
              s.ticks = s.ticks.filter((x) => x > tick - p.span)
            }
            return s
          })
          for (let i = 0; i < ps.length && !denier; i++) {
            const p = ps[i], s = sts[i]
            const ok = p.kind === 'bucket' ? s.v >= p.per : BigInt(s.ticks.length) < p.limit
            if (!ok) denier = p.name
          }
          if (!denier) {
            ps.forEach((p, i) => {
              if (p.kind === 'bucket') sts[i].v -= p.per
              else sts[i].ticks.push(tick)
            })
          }
        }
        if (mode === 'replay') out.push(`${t[1]} ${key} ${denier ? 'deny ' + denier : 'allow'}`)
        const st = stats.get(key) || { a: 0, d: 0 }
        if (denier) st.d++; else st.a++
        stats.set(key, st)
      }
    } catch (e) {
      if (e instanceof Fail) return { err: `error: line ${n}: ${e.message}\n` }
      throw e
    }
  }
  if (mode === 'summary') {
    let a = 0, d = 0
    for (const k of [...stats.keys()].sort((x, y) => (x < y ? -1 : x > y ? 1 : 0))) {
      const s = stats.get(k)
      a += s.a; d += s.d
      out.push(`${k} allowed=${s.a} denied=${s.d}`)
    }
    out.push(`total allowed=${a} denied=${d}`)
  }
  return { out: out.length ? out.join('\n') + '\n' : '' }
}

let input = ''
process.stdin.setEncoding('utf8')
process.stdin.on('data', (c) => { input += c })
process.stdin.on('end', () => {
  const r = run(input)
  if (r.err) { process.stderr.write(r.err); process.exitCode = 2 } else process.stdout.write(r.out)
})
